import sys

def is_palindrome(s):
    return s == s[::-1]

def main():
    s = sys.stdin.read().strip()
    n = len(s)

    for i in range(n + 1):
        for char in 'abcdefghijklmnopqrstuvwxyz':
            new_s = s[:i] + char + s[i:]
            if is_palindrome(new_s):
                print(new_s)
                return

    print("NA")

main()
